sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    /*
    This script will insert a record in HSBC SWB Outbound Tables
    when there is insert or update on the HSBC Email Case Task
    */
    // Added as a part of MSSOTIQUBE-200
	// Reviewed as part of 1097.
    try {
        var emailNumber = current.parent.email_number.sys_id;
        var emailCase = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
        if (emailCase.get(emailNumber)) { // modified to optimize as per MSSOTIQUBE - 200
            current.state = "2";

            current.setWorkflow(false);
            current.update();
            current.setWorkflow(true);


            var swb = new GlideRecord('x_hsb11_hsbcmss_sw_hsbc_swb_outbound_table');
            swb.initialize();
            swb.servicenow_task_id = current.sys_id;
            swb.recipientemail = emailCase.recipients;
            swb.senderemail = emailCase.from;
            swb.email_subject = emailCase.subject;
            swb.email_body = emailCase.body;
            swb.qtrack_id = current.qtrack_id;
            swb.email_attachments = emailCase.attachment;
            swb.receive_at = emailCase.sys_created_on;
            swb.state = 'Ready to be sent';
            swb.insert();

            var res = {};
            res["status"] = "Success";
            res["message"] = "Record submitted for SWB Extraction";


            current.work_notes = JSON.stringify(res);

            current.setWorkflow(false);
            current.update();
			current.setWorkflow(true);

        }
    } catch (err) {
        gs.info("Error captured from business rule - HSBC-Record creation on swb outbound " + err);
    }




})(current, previous);
